-- Guia "Aveiro em 3 dias: ingresso combinado dos museus de € 5 (cerca de R$ 33) e museus fechados às segundas" (rascunho). Gerado por tools/gerar-migration-guia.ts a partir de content/guias/aveiro-em-3-dias.json.
-- Entra como rascunho: publique pelo painel (/admin-blog.html) depois de conferir a pré-visualização.
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes)
VALUES ('d0b1b2b6-0026-42ba-8ca8-246e1a948f16', 'aveiro-em-3-dias', 'draft', 'portugal', 'Aveiro em 3 dias: ingresso combinado dos museus de € 5 (cerca de R$ 33) e museus fechados às segundas', 'ingresso combinado dos museus de € 5 (cerca de R$ 33)', 'Roteiro de Aveiro em 3 dias com museus de ingresso combinado, Costa Nova e Barra de ônibus, Ecomuseu da Troncalhada, miradouro da Ria e ovos moles, valores em euros e em reais e o guia em PDF grátis.', 'Os museus de Aveiro fecham às segundas: monte a viagem para terça a domingo. O roteiro, os valores e o guia completo vão no celular.', 'Aveiro', NULL, '/assets/blog/aveiro-3-dias.jpg', '/assets/blog/aveiro-3-dias-m.jpg', 'Barcos moliceiros no canal de Aveiro ao pôr do sol', 0, '[{"t":"pdf","href":"/guias/aveiro-em-3-dias.pdf","note":"PDF de 16 páginas, feito para ler no celular. Grátis, sem cadastro."},{"t":"p","text":"Museus com ingresso combinado, Costa Nova e Barra de ônibus, Ecomuseu da Troncalhada, miradouro da Ria e ovos moles, com horários, valores em euro e em reais e checklist."},{"t":"tip","items":["Os museus de Aveiro fecham às segundas. Monte a viagem para terça a domingo.","Três dias: centro e museus, Costa Nova e Barra, salinas e Ria. Essa ordem é recomendação da Rota Certa.","Brasileiro entra sem visto para turismo. Veja a seção Documentos e antes de ir.","O Museu de Santa Joana, fechado por obras desde 06/10/2026, fica fora do roteiro."],"title":"Como usar este roteiro"},{"t":"whatsapp"},{"t":"afiliado"},{"t":"h","text":"Centro e Arte Nova","label":"Dia 1"},{"t":"p","text":"Estação com azulejos, os dois museus do ingresso combinado e a Ria, a pé. Faça este dia de terça a domingo."},{"t":"img","src":"/assets/blog/aveiro-canal.jpg","alt":"Canal de Aveiro com casario e barcos tradicionais","caption":"Casario e barcos tradicionais no canal de Aveiro.","credit":"Foto: Egor Kunovsky / Pexels","w":1000,"h":750},{"t":"ul","items":["**10h, Antiga estação e Loja ESTAÇÃO:** A fachada tem 59 painéis de azulejo. A loja de turismo abre às 10h e vende o ingresso combinado.","**10h30, Museu Arte Nova:** Casa Major Pessoa, edifício Art Nouveau de pedra, ferro forjado e azulejos. Entra no combinado de € 5 (cerca de R$ 33).","**12h30 às 13h30, Pausa de almoço dos museus:** Os dois museus fecham nesse intervalo.","**13h30, Museu da Cidade:** Rua João Mendonça, 9/11. Entra no combinado. Salas abertas até 15 minutos antes das 18h.","**15h30, Opcional, passeio de moliceiro:** Operador privado, no Largo do Rossio. Preço, duração e horário: consulte o [operador](https://passeiodemoliceiro.com/en)."]},{"t":"tip","items":["Faça este dia de terça a domingo. Confira no [site dos museus de Aveiro](https://museusdeaveiro.cm-aveiro.pt/bilhetica) se há entrada grátis no primeiro domingo do mês."],"title":"Primeiro domingo do mês"},{"t":"tip","items":["Principal: Museu Arte Nova e Museu da Cidade, com ingresso combinado de € 5 (cerca de R$ 33)","Grátis: sem atração gratuita confirmada neste dia","Opcional: passeio de moliceiro, com operador privado","**Nas atrações:** entre as 10h e as 18h, no horário dos museus","**A pé:** trajeto curto, dentro do centro","**Esforço:** leve, por causa do trajeto curto","Estimativas da Rota Certa, não dados oficiais. Os horários sugeridos de passeio também são recomendação nossa.","**Dica da Rota Certa:** compre o ingresso combinado na Loja ESTAÇÃO, que abre às 10h, antes do primeiro museu."],"title":"Para planejar o Dia 1"},{"t":"p","text":"[Abrir a rota do Dia 1 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Antiga%20Esta%C3%A7%C3%A3o%20de%20Aveiro&waypoints=Museu%20Arte%20Nova%2C%20Aveiro&destination=Museu%20da%20Cidade%2C%20Aveiro&travelmode=walking)"},{"t":"passeio","busca":"Aveiro passeio de barco moliceiro","title":"Passeios de barco em Aveiro"},{"t":"h","text":"Costa Nova e Barra","label":"Dia 2"},{"t":"p","text":"Palheiros de riscas, praia e o farol mais alto de Portugal. Faça este dia de terça a domingo, por causa do Museu Marítimo de Ílhavo."},{"t":"img","src":"/assets/blog/aveiro-costa-nova.jpg","alt":"Casas listradas da Costa Nova","caption":"Casas listradas da Costa Nova.","credit":"Foto: Laura Lee Van Herck / Pexels","w":1000,"h":667},{"t":"ul","items":["**09h35, Terminal Rodoviário de Aveiro, linha 36:** Partida às 09:35, diária (horário de 1/9/2025). Duração: consulte a [BusWay](https://busway-cira.pt/linhas/36-ida/).","**Manhã, Costa Nova, palheiros:** Localidade do município de Ílhavo, entre a ria e o mar. As casas de madeira com riscas coloridas foram feitas por pescadores de Ílhavo depois de 1808.","**Almoço, Praia da Costa Nova:** Praia de areia dourada. Reserve a hora do almoço para a orla.","**Tarde, Farol da Barra:** 62 m, o mais alto de Portugal (turismo de Ílhavo). Linha 36: paragem Farol Forte da Barra.","**Opcional, Museu Marítimo de Ílhavo:** Terça a domingo, 10h às 13h e 14h às 18h. Adulto € 6 (cerca de R$ 39); com o Navio-Museu Santo André, € 8 (cerca de R$ 52). Fechado às segundas."]},{"t":"tip","items":["A linha 36 da BusWay liga o Terminal Rodoviário de Aveiro à Costa Nova. Ida, do Terminal: 09:35, 12:15, 13:00, 17:00 e 17:50. Volta, do Largo Arrais Ançã, na Costa Nova: 16:25, 18:10 e 18:45. Paragens: Terminal Rodoviário, Forte da Barra Ferry, Farol Forte da Barra e Largo Arrais Ançã.","Horários em vigor desde 1/9/2025, todos os dias, e os tempos de passagem são indicativos. Tarifa e tempo de viagem não foram confirmados: consulte a BusWay ([ida](https://busway-cira.pt/linhas/36-ida/) e [volta](https://busway-cira.pt/linhas/36-volta/))."],"title":"Ônibus à Costa Nova: linha 36"},{"t":"tip","items":["Não confirmamos se há visita por dentro do Farol da Barra, nem o preço. Consulte o [turismo de Ílhavo](https://www.visitilhavo.pt/o-que-te-faz-feliz/cultura-e-museus/farol-da-barra)."],"title":"Visita por dentro do Farol"},{"t":"tip","items":["Principal: palheiros da Costa Nova e Farol da Barra","Grátis: sem atração gratuita confirmada neste dia","Opcional: Museu Marítimo de Ílhavo, fechado às segundas","**Nas atrações:** entre o ônibus das 09:35 e a volta das 16:25, 18:10 ou 18:45","**A pé:** pelas ruas da Costa Nova e da Barra; veja a distância no mapa","**Esforço:** médio, por causa do ônibus e do dia fora do centro","Estimativas da Rota Certa, não dados oficiais. Os horários sugeridos de passeio também são recomendação nossa.","**Dica da Rota Certa:** faça este dia de terça a domingo, por causa do Museu Marítimo."],"title":"Para planejar o Dia 2"},{"t":"p","text":"[Abrir a rota do Dia 2 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Terminal%20Rodovi%C3%A1rio%20de%20Aveiro&destination=Farol%20da%20Barra%2C%20Gafanha%20da%20Nazar%C3%A9&travelmode=transit)"},{"t":"passeio","busca":"Aveiro Costa Nova passeio","title":"Passeios na Costa Nova e na Barra"},{"t":"h","text":"Salinas e Ria","label":"Dia 3"},{"t":"p","text":"Ecomuseu Marinha da Troncalhada, miradouro da Ria e um doce típico, em ritmo calmo."},{"t":"img","src":"/assets/blog/aveiro-ria.jpg","alt":"Ria de Aveiro ao pôr do sol com barcos tradicionais","caption":"Pôr do sol na ria de Aveiro.","credit":"Foto: Simão Moreira / Pexels","w":1000,"h":667},{"t":"ul","items":["**10h, Ecomuseu Marinha da Troncalhada:** Ao ar livre, sem horário fixo e gratuito. Vá a pé ou de [BUGA](https://buga.cm-aveiro.pt) (bicicleta partilhada). Veja a distância no mapa.","**11h30, Miradouro Cais do Sal:** Na Estrada Cais do Sal, antiga estrada dique, junto ao Ecomuseu. Ponto de observação da Ria listado pela Câmara de Aveiro.","**13h, Ovos moles:** Doce com nome protegido: \"Ovos Moles de Aveiro\" é Indicação Geográfica Protegida da União Europeia desde 2009. Não indicamos loja, porque não há fonte oficial de estabelecimento.","**Tarde, Tempo livre:** Volte ao centro ou ao canal com calma."]},{"t":"tip","items":["A página oficial do Ecomuseu é curta. Pergunte na Loja Turismo & Museus se há alguma regra de visita no dia."],"title":"Regra de visita do Ecomuseu"},{"t":"tip","items":["Fechado desde 06/10/2026, com obra prevista de 18 meses e reabertura sem data. Por isso ele não entra neste roteiro. Novidades no [portal Região de Aveiro](https://www.regiaodeaveiro.pt/comunicacao/noticias/noticia/museu-de-santa-joana-encerra-temporariamente-devido-as-obras)."],"title":"Museu de Santa Joana: fechado"},{"t":"tip","items":["Principal: Ecomuseu Marinha da Troncalhada","Grátis: entrada do Ecomuseu, para todas as idades","Opcional: ovos moles, doce típico de Aveiro","**Nas atrações:** 3 paradas, em ritmo calmo","**A pé:** a pé ou de BUGA; veja a distância no mapa","**Esforço:** baixo, em ritmo calmo","Estimativas da Rota Certa, não dados oficiais. Os horários sugeridos de passeio também são recomendação nossa.","**Dica da Rota Certa:** se o Dia 3 for o último da viagem, deixe a mala guardada onde estiver hospedado."],"title":"Para planejar o Dia 3"},{"t":"p","text":"[Abrir a rota do Dia 3 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Ecomuseu%20Marinha%20da%20Troncalhada%2C%20Aveiro&destination=Miradouro%20Cais%20do%20Sal%2C%20Aveiro&travelmode=walking)"},{"t":"passeio","busca":"Aveiro Ria passeio","title":"Passeios na Ria de Aveiro"},{"t":"h","text":"Museus de Aveiro: ingressos e horários","label":"Atração principal"},{"t":"p","text":"O combinado do Museu da Cidade com o Museu Arte Nova custa € 5 (cerca de R$ 33) para 25 a 64 anos. Separados, cada um custa € 4 (cerca de R$ 26) para essa faixa. O Ecomuseu é gratuito."},{"t":"ul","items":["**25 a 64 anos:** € 5 (cerca de R$ 33).","**65 anos ou mais:** € 2,50 (cerca de R$ 17).","**6 a 24 anos:** € 1,25 (cerca de R$ 9).","**0 a 5 anos:** gratuito."]},{"t":"tip","items":["Terça a domingo, 10h às 12h30 e 13h30 às 18h. Acesso às salas até 15 minutos antes de fechar. Fechados: segundas, 1 de janeiro, domingo de Páscoa, 1 de maio e 25 de dezembro."],"title":"Horário"},{"t":"tip","items":["Menores de 6 anos e dias comemorativos: 12 de maio, 18 de maio, 18 de abril, Noite Europeia dos Museus e Jornadas Europeias do Património.","Confira no [site dos museus de Aveiro](https://museusdeaveiro.cm-aveiro.pt/bilhetica) se há entrada grátis no primeiro domingo do mês."],"title":"Entradas gratuitas"},{"t":"ul","items":["**Onde comprar:** Loja Turismo & Museus, no Museu da Cidade, e Loja ESTAÇÃO, na antiga estação, diariamente das 10h às 12h30 e das 13h30 às 18h. O Museu de Santa Joana está fechado desde 06/10/2026."]},{"t":"h","text":"Como chegar e se locomover","label":"Na prática"},{"t":"p","text":"A pé no centro, ônibus no Dia 2, a pé ou de bicicleta no Dia 3."},{"t":"ul","items":["**Trem até Aveiro:** De Aveiro há trem direto para Lisboa e para o Porto. Horário, duração e preço não confirmados: o preço da CP varia por percurso, classe, desconto e antecedência, então use o buscador em [cp.pt](https://cp.pt/info/prices-alfa-pendular). Telefone CP: 808 208 208.","**Do trem ao centro:** A antiga estação, onde fica a Loja ESTAÇÃO, está no Largo da Estação. Ao centro a pé: curto, veja no mapa.","**Ônibus para a Costa Nova e a Barra:** BusWay, linhas 34 (Aveiro e Ílhavo), 35 (Aveiro e Praia da Barra, só em julho e agosto), 36 (Aveiro e Costa Nova) e 70 (Costa Nova e Ílhavo). Telefone gratuito da BusWay: 800 101 012. Tarifa, tempo de viagem e horários das linhas 34 e 70 não foram confirmados.","**Bicicleta BUGA:** Diariamente das 08h às 20h, com 20 estações e 280 docas: retire numa e devolva noutra. App para iOS e Android; cartão físico no Museu da Cidade e na antiga estação. Tarifa não confirmada: veja o [site da BUGA](https://buga.cm-aveiro.pt).","**Passeio de moliceiro:** Operador privado. Preço, duração e horário: consulte o [operador](https://passeiodemoliceiro.com/en).","**Passeios guiados na Costa Nova e na Barra:** De bicicleta e a pé, vendidos por um operador privado (Balão Mágico), com reserva de pelo menos 1 dia de antecedência. Sem preço neste guia: veja os [roteiros do turismo de Ílhavo](https://www.visitilhavo.pt/planeia-a-tua-viagem/roteiros/visitas-orientadas/praias-da-costa-nova-e-da-barra)."]},{"t":"h","text":"Onde comer","label":"Sabores"},{"t":"p","text":"Em Aveiro, o doce típico tem nome protegido pela União Europeia."},{"t":"ul","items":["**Ovos moles:** \"Ovos Moles de Aveiro\" é Indicação Geográfica Protegida (Regulamento 286/2009, de 7/4/2009). A especificação foi alterada em 2015. Não indicamos loja.","**Mariscos da Ria de Aveiro:** O roteiro do turismo de Ílhavo tem o passeio \"Tudo sobre mariscos na Ria de Aveiro\", com encontro no Mercado do Peixe da Costa Nova, vendido por um operador privado. Sem preço neste guia.","**Casa de Chá no Museu Arte Nova:** O Turismo Centro de Portugal cita uma Casa de Chá no edifício. O horário dela não entra neste guia."]},{"t":"tip","items":["Este guia não traz preço de refeição nem indica restaurante, por falta de fonte oficial. Veja o cardápio na porta antes de sentar."],"title":"Preços de restaurante"},{"t":"tip","items":["**Dica da Rota Certa:** no Dia 1, use a pausa de almoço dos museus (12h30 às 13h30). No Dia 2, reserve o almoço para a orla da Costa Nova."]},{"t":"h","text":"Documentos e antes de ir","label":"Checklist"},{"t":"tip","items":["O Brasil consta do Anexo II do Regulamento (UE) 2018/1806: estadas de até 90 dias em qualquer período de 180 dias não precisam de visto. O passaporte deve ter sido emitido nos últimos 10 anos e valer pelo menos 3 meses depois da saída prevista da UE."],"title":"Passaporte, sem visto para turismo"},{"t":"ul","items":["**Na chegada: digitais e foto:** O EES (Sistema de Entrada e Saída) opera em todos os países Schengen desde 10/4/2026. Registra dados do passaporte, imagem facial e impressões digitais, e não é preciso pedir antes. O pré-cadastro, opcional, vai até 72 horas antes pelo app Travel to Europe.","**ETIAS e meios de subsistência:** Confira as regras de entrada vigentes nos sites oficiais: [ETIAS](https://home-affairs.ec.europa.eu/policies/schengen/smart-borders/european-travel-information-authorisation-system_en) e [Your Europe](https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm). Faça isso antes de comprar a passagem."]},{"t":"tip","items":["Passaporte emitido nos últimos 10 anos e válido 3 meses além da saída.","Regras de entrada vistas nos sites oficiais.","Roteiro montado para terça a domingo (museus fecham às segundas).","Horário do ônibus da linha 36 visto na BusWay.","Ingresso combinado dos museus, comprado numa loja de turismo."],"title":"Checklist"},{"t":"h","text":"Orçamento","label":"Planejamento"},{"t":"p","text":"O preço da passagem não é o preço da viagem."},{"t":"tip","items":["Passagens e bagagem","Hospedagem","Seguro viagem","Aeroporto e transporte","Ingressos","Alimentação","Imprevistos"],"title":"O que entra no seu orçamento"},{"t":"p","text":"Por adulto (25 a 64 anos), só com preço oficial:"},{"t":"ul","items":["**Combinado dos museus:** € 5 (cerca de R$ 33).","**Combinado mais Museu Marítimo de Ílhavo:** € 11 (cerca de R$ 72), somando € 5 (cerca de R$ 33) e € 6 (cerca de R$ 39).","**Combinado mais o integrado Museu Marítimo e Navio-Museu:** € 13 (cerca de R$ 85), somando € 5 (cerca de R$ 33) e € 8 (cerca de R$ 52).","**Ecomuseu:** grátis."]},{"t":"p","text":"Trem, ônibus, BUGA, moliceiro, Farol, refeições e hospedagem não entram, por falta de preço oficial confirmado. Reais pelo euro de venda do Banco Central de 19/11/2026: € 1 = R$ 6,4672, arredondados para cima. No cartão entram o IOF e o câmbio do banco."},{"t":"pdf","href":"/guias/aveiro-em-3-dias.pdf","note":"Leve o roteiro, as rotas e o orçamento no celular. Grátis, sem cadastro."},{"t":"h","text":"Valores oficiais e fontes","label":"Transparência"},{"t":"p","text":"Conferido em 19/11/2026 nos sites abaixo. Reais pelo euro de venda do Banco Central de 19/11/2026 (€ 1 = R$ 6,4672), arredondados para cima. Itens que o guia não confirmou aparecem como \"consulte\" ou \"confira\". Preços e regras mudam: confira antes de ir."},{"t":"tip","items":["Museus de Aveiro: [bilhética](https://museusdeaveiro.cm-aveiro.pt/bilhetica), [horário](https://museusdeaveiro.cm-aveiro.pt/horario) e [página dos museus](https://www.cm-aveiro.pt/visitantes/visitar/patrimonio-edificado/museus-de-aveiro)","Santa Joana: [Região de Aveiro](https://www.regiaodeaveiro.pt/comunicacao/noticias/noticia/museu-de-santa-joana-encerra-temporariamente-devido-as-obras) e [aviso dos museus](https://museusdeaveiro.cm-aveiro.pt)","Câmara de Aveiro: [lojas de turismo](https://www.cm-aveiro.pt/visitantes/visitar/turismo-municipal), [antiga estação](https://www.cm-aveiro.pt/visitantes/visitar/patrimonio-cultural/antiga-estacao-da-cp-aveiro), [miradouros](https://www.cm-aveiro.pt/visitantes/visitar/ria-de-aveiro-pontos-de-observacao) e [BUGA](https://buga.cm-aveiro.pt)","Arte Nova: [Turismo Centro de Portugal](https://centerofportugal.com/entity/art-nouveau-museum)","Ílhavo: [Costa Nova](https://www.visitilhavo.pt/costa-nova-do-prado), [Farol da Barra](https://www.visitilhavo.pt/o-que-te-faz-feliz/cultura-e-museus/farol-da-barra), [ônibus](https://www.visitilhavo.pt/planeia-a-tua-viagem/chegar-e-circular/por-terra/autocarro), [trem](https://www.visitilhavo.pt/planeia-a-tua-viagem/chegar-e-circular/por-terra/comboio) e [roteiros](https://www.visitilhavo.pt/planeia-a-tua-viagem/roteiros/visitas-orientadas/praias-da-costa-nova-e-da-barra)","BusWay: [linha 36 ida](https://busway-cira.pt/linhas/36-ida/), [volta](https://busway-cira.pt/linhas/36-volta/) e [linha 35](https://busway-cira.pt/linhas/L35/)","Museu Marítimo: [horário](https://museumaritimo.cm-ilhavo.pt/) e [bilheteira](https://museumaritimo.cm-ilhavo.pt/visitar/bilheteira). CP: [preços](https://cp.pt/info/prices-alfa-pendular)","Moliceiro: [operador privado](https://passeiodemoliceiro.com/en)","Ovos moles: [Reg. 286/2009](https://eur-lex.europa.eu/legal-content/PT/TXT/?uri=CELEX:32009R0286) e [Reg. 2015/1743](https://eur-lex.europa.eu/eli/reg/2015/1743/oj)","Entrada: [Reg. 2018/1806](https://eur-lex.europa.eu/legal-content/PT/TXT/?uri=CELEX:32018R1806), [Your Europe](https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm), [EES](https://home-affairs.ec.europa.eu/news/main-differences-between-ees-and-etias-what-travellers-need-know-2026-04-28_en) e [ETIAS](https://home-affairs.ec.europa.eu/policies/schengen/smart-borders/european-travel-information-authorisation-system_en)","Câmbio: [Banco Central, 19/11/2026](https://www4.bcb.gov.br/Download/fechamento/20261119.csv)"],"title":"Fontes oficiais, conferidas em 19/11/2026"},{"t":"tip","items":["Se há entrada grátis no primeiro domingo do mês nos museus: confira no site dos museus de Aveiro","Preço, duração e horário do passeio de moliceiro","Horário, duração e preço do trem para Aveiro (CP)","Tarifa e tempo de viagem do ônibus, e horários das linhas 34 e 70 (BusWay); os da linha 36 são de 1/9/2025","Tarifa da bicicleta BUGA","Visita por dentro do Farol da Barra: horário e preço","Quando o Museu de Santa Joana reabre: está fechado desde 06/10/2026, com obra prevista de 18 meses e sem data de reabertura","Horário do Museu Arte Nova em outras fontes: vale o do site oficial dos museus","Regra de visita e acesso ao Ecomuseu Marinha da Troncalhada no dia","Data de início do ETIAS","Valor dos meios de subsistência exigido na entrada em Portugal","Preço de refeições, hospedagem e táxi: fora do guia"],"title":"O que este guia não informa"},{"t":"p","text":"Preços, horários e regras mudam: confira nas fontes acima antes de ir. As estimativas de tempo e esforço, a ordem dos dias, os horários sugeridos de passeio e as dicas marcadas como da Rota Certa são recomendações nossas, não dados oficiais."},{"t":"p","text":"Foto de capa: Nasta Dragun / Pexels."},{"t":"whatsapp"},{"t":"p","text":"Quer montar o roteiro da viagem inteira? Use o [Planner grátis da Rota Certa](https://rotacertapassagens.com/#/planner)."},{"t":"contato"},{"t":"afiliado"}]', 11);
